const discountedTotalCost = originalTotalCost - discountAmount;
const earnedFromSelling = sellingPricePerCD * cdsToSell;
const remainingCDs = numberOfCDs - cdsToSell;
const costOfRemainingCDs = remainingCDs * originalPrice;

const totalEarned = earnedFromSelling;
const totalCost = discountedTotalCost;
const loss = totalCost - totalEarned;

console.log(loss);
```

